import { test, expect } from '@playwright/test';

test.describe('Homepage Hero Section Responsive Design', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display hero section with mobile layout on small screens', async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });

    // Wait for hero section to be visible
    const heroSection = page.getByRole('region', { name: /hero/i });
    await expect(heroSection).toBeVisible();

    // Check that hero content is stacked vertically on mobile
    const heroHeading = page.getByRole('heading', { level: 1 });
    await expect(heroHeading).toBeVisible();

    // Verify mobile-specific styling is applied
    const heroContainer = page.getByRole('region', { name: /hero/i });
    const boundingBox = await heroContainer.boundingBox();

    // Hero section should take full width on mobile
    expect(boundingBox?.width).toBeLessThanOrEqual(375);
  });

  test('should display hero section with desktop layout on large screens', async ({ page }) => {
    // Set desktop viewport
    await page.setViewportSize({ width: 1920, height: 1080 });

    // Wait for hero section to be visible
    const heroSection = page.getByRole('region', { name: /hero/i });
    await expect(heroSection).toBeVisible();

    // Check that hero content is visible
    const heroHeading = page.getByRole('heading', { level: 1 });
    await expect(heroHeading).toBeVisible();

    // Verify desktop layout is applied
    const heroContainer = page.getByRole('region', { name: /hero/i });
    const boundingBox = await heroContainer.boundingBox();

    // Hero section should have appropriate width on desktop
    expect(boundingBox?.width).toBeGreaterThan(1000);
  });

  test('should have readable text on mobile hero section', async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });

    // Check hero heading is readable
    const heroHeading = page.getByRole('heading', { level: 1 });
    await expect(heroHeading).toBeVisible();

    // Verify text is not cut off
    const headingBox = await heroHeading.boundingBox();
    expect(headingBox?.width).toBeGreaterThan(0);
    expect(headingBox?.height).toBeGreaterThan(0);

    // Check for call-to-action button visibility on mobile
    const ctaButton = page.getByRole('button', { name: /get started|learn more|shop now/i });
    if (await ctaButton.isVisible()) {
      expect(ctaButton).toBeVisible();
    }
  });

  test('should maintain aspect ratio of hero image on mobile', async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });

    // Find hero image
    const heroImage = page.getByRole('img', { name: /hero|banner/i }).first();

    if (await heroImage.isVisible()) {
      const imageBoundingBox = await heroImage.boundingBox();

      // Image should be visible and have dimensions
      expect(imageBoundingBox?.width).toBeGreaterThan(0);
      expect(imageBoundingBox?.height).toBeGreaterThan(0);

      // Image should not exceed viewport width
      expect(imageBoundingBox?.width).toBeLessThanOrEqual(375);
    }
  });
});
